<button class="calc-btn" data-v="0" style="grid-column:span 2">0</button><button class="calc-btn" data-v=".">,</button><button class="calc-btn eq" data-a="eq">=</button>
</div><div class="calc-note">También podés usar el teclado numérico, +, −, ×, ÷, Enter y Escape.</div></section></main><script>
(()=>{const d=document.getElementById('display');let expr='';const show=()=>{d.value=expr||'0'};const add=v=>{if(expr.length<80){expr+=v;show()}};const calc=()=>{try{if(!expr)return;const safe=expr.replace(/%/g,'/100');if(!/^[0-9+\-*/.()\s]+$/.test(safe))throw 0;const r=Function('"use strict";return ('+safe+')')();if(!Number.isFinite(r))throw 0;expr=String(Math.round((r+Number.EPSILON)*100000000)/100000000);show()}catch(e){d.value='Error';expr=''}};document.querySelectorAll('.calc-btn').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.v)add(b.dataset.v);else if(b.dataset.a==='clear'){expr='';show()}else if(b.dataset.a==='back'){expr=expr.slice(0,-1);show()}else if(b.dataset.a==='eq')calc()}));window.addEventListener('keydown',e=>{if(/[0-9.+\-*/%()]/.test(e.key)&&e.key.length===1){add(e.key);e.preventDefault()}else if(e.key==='Enter'||e.key==='='){calc();e.preventDefault()}else if(e.key==='Backspace'){expr=expr.slice(0,-1);show();e.preventDefault()}else if(e.key==='Escape'){expr='';show();e.preventDefault()}});})();
</script></body></html>
